SELECT id, name, aliases, era, birth_year, death_year, description, biography, status FROM jsonb_populate_recordset(NULL::public.person, '[{"status": "draft", "name": "朱元璋", "aliases": [], "era": "元末明初", "birth_year": null, "death_year": null, "description": "钟离人，少因饥疫丧家出家皇觉寺，1352年投郭子兴于濠州，后娶其养女。", "biography": null, "id": "3d83c7c6-23fc-5e89-9e9b-b70713a0a63e"}, {"name": "康茂才", "aliases": [], "era": "元", "birth_year": null, "death_year": null, "description": "水寨元帅，集庆陷后率众降朱。", "biography": null, "status": "draft", "id": "f04c265d-38f9-5b72-9c39-567870658cd2"}, {"name": "邓愈", "aliases": [], "era": "元", "birth_year": null, "death_year": null, "description": "1355年从朱元璋设伏擒陈埜先。", "biography": null, "status": "draft", "id": "5fbf3347-c8f3-5eaa-aa83-d0681e64b192"}, {"status": "draft", "name": "陈友谅", "aliases": [], "era": "元", "birth_year": null, "death_year": null, "description": "沔阳渔家子，曾为县小吏，1351年来从徐寿辉，父名普才。", "biography": null, "id": "14cfdd00-af11-50e5-9fdb-22c478b7fdec"}, {"name": "赵普胜", "aliases": [], "era": "元", "birth_year": null, "death_year": null, "description": "1352年据池阳，被桑节军进攻。", "biography": null, "status": "draft", "id": "33efcd40-36d5-5acb-ba65-eb53795208c8"}, {"status": "draft", "name": "刘福通", "aliases": [], "era": "元", "birth_year": null, "death_year": null, "description": "1351年与韩山童等筹起兵，事发后以红巾起事攻陷颍州，后攻河南多地。", "biography": null, "id": "bb43c0fa-e764-55ad-a47a-f24d9349e961"}, {"status": "draft", "name": "韩林儿", "aliases": [], "era": "元", "birth_year": null, "death_year": null, "description": "韩山童之子，父被擒后与杨氏逃武安。", "biography": null, "id": "15a71da9-cd6f-5a0b-ba68-144469ebde18"}, {"name": "胡大海", "aliases": [], "era": "元", "birth_year": null, "death_year": null, "description": "吴将，常州夹击援军。", "biography": null, "status": "draft", "id": "9608d085-9e6c-528f-bbb3-143306d2efb9"}, {"status": "draft", "name": "舒穆嚕宜逊", "aliases": [], "era": "元", "birth_year": null, "death_year": null, "description": "先世辽人，元前沿海副万户，方国珍起兵后守温州，后升浙东宣慰使并筑处州城。", "biography": null, "id": "57c38703-ff0e-5e3a-81e7-b75a934fc2c6"}, {"name": "德济（胡大海养子）", "aliases": [], "era": "元", "birth_year": null, "death_year": null, "description": "1358年梅花门外击破援婺军，仅名不补胡姓。", "biography": null, "status": "draft", "id": "16116020-6089-5247-bd1c-4d587ccc4588"}, {"name": "舒穆嚕厚逊", "aliases": [], "era": "元", "birth_year": null, "death_year": null, "description": "舒穆嚕宜逊弟，守婺州，1358年被执。", "biography": null, "status": "draft", "id": "e496b3e4-559e-5426-99e3-b78cbdf40ab3"}, {"name": "王宗显（吴宁越知府）", "aliases": [], "era": "元", "birth_year": null, "death_year": null, "description": "和州儒士，1358年任知府开郡学。", "biography": null, "status": "draft", "id": "0a0e49d9-c6b5-53f7-915f-19a6f513a8c4"}, {"status": "draft", "name": "方国珍", "aliases": [], "era": "元", "birth_year": null, "death_year": null, "description": "家世海贩盐，1348年因仇家指控通寇杀仇入海聚众，执元将并拒授定国尉，1350年再攻温州。", "biography": null, "id": "13233500-bcaf-50d6-822a-fd99bc0ec709"}, {"name": "关（方国珍次子）", "aliases": [], "era": "元末", "birth_year": null, "death_year": null, "description": "方国珍次子，被送至朱元璋处为质，朱遣归。", "biography": null, "status": "draft", "id": "2e977567-330c-5a4b-93e5-5b99a5b19319"}, {"name": "俞通海", "aliases": [], "era": "元", "birth_year": null, "death_year": null, "description": "1355年导巢湖军附朱元璋，领水军渡江。", "biography": null, "status": "draft", "id": "eff73aa1-e4e3-5022-b155-bf9d88812371"}, {"name": "察罕特穆尔", "aliases": [], "era": "元", "birth_year": null, "death_year": null, "description": "北庭后裔，居沈丘，与李思齐起兵，授汝宁达噜噶齐。", "biography": null, "status": "draft", "id": "59a5e251-37f4-5986-9511-962d04ceea90"}, {"name": "常遇春", "aliases": [], "era": "元", "birth_year": null, "death_year": null, "description": "怀远人，1355年投朱元璋、采石先登。", "biography": null, "status": "draft", "id": "51d50a75-07e1-574f-b22d-1fded66288ff"}, {"name": "宋巴延布哈（元黄岩达噜噶齐）", "aliases": [], "era": "元", "birth_year": null, "death_year": null, "description": "1354年被方国珍拘待诏。", "biography": null, "status": "draft", "id": "aae4a889-81a7-5087-a947-68f298bea43c"}, {"name": "夏煜", "aliases": [], "era": "元", "birth_year": null, "death_year": null, "description": "朱元璋下集庆后录用儒士。", "biography": null, "status": "draft", "id": "033b7a2f-3cb8-51a8-9132-06909c2af1c5"}, {"name": "袁天禄（元福建参政）", "aliases": [], "era": "元", "birth_year": null, "death_year": null, "description": "元福建行省参政，1360年派古田县尹林文广经海路向吴纳款。", "biography": null, "status": "draft", "id": "f2107846-6e3d-5662-9643-50364b9f79d5"}, {"name": "刘基", "aliases": [], "era": "元", "birth_year": null, "death_year": null, "description": "青田人，反对招抚方国珍被谪，曾任儒学副提举。", "biography": null, "status": "draft", "id": "bb5b8872-dbd3-576b-b02d-3b844e5a38e7"}, {"name": "宋濂", "aliases": [], "era": "元", "birth_year": null, "death_year": null, "description": "宁越受延五经师。", "biography": null, "status": "draft", "id": "6c23ee16-fcbd-5f1e-be7b-f121a950707e"}, {"name": "章溢", "aliases": [], "era": "元", "birth_year": null, "death_year": null, "description": "被舒穆嚕宜逊辟为军谋。", "biography": null, "status": "draft", "id": "980a723b-2735-561e-b243-7642fe3cf3bd"}, {"name": "叶琛", "aliases": [], "era": "元", "birth_year": null, "death_year": null, "description": "被舒穆嚕宜逊辟为军谋。", "biography": null, "status": "draft", "id": "e2253684-65f4-5429-b70d-c680b5a4de54"}, {"name": "徐达", "aliases": [], "era": "元", "birth_year": null, "death_year": null, "description": "濠州人，1353年随朱元璋南略。", "biography": null, "status": "draft", "id": "0f28446e-78b0-5db1-9677-98777005803e"}, {"name": "朱文逊（朱元璋养子）", "aliases": [], "era": "元末", "birth_year": null, "death_year": null, "description": "朱元璋养子，太平城守将，陈军攻城时战死。", "biography": null, "status": "draft", "id": "aee69561-ef31-562f-bf98-d3e29cc4a822"}, {"name": "花云", "aliases": [], "era": "元", "birth_year": null, "death_year": null, "description": "怀远人，1353年夜袭横涧山、先驱取滁。", "biography": null, "status": "draft", "id": "8b40b7c8-2363-5db1-a37c-d1b61a7332ba"}, {"name": "王鼎（朱元璋太平院判）", "aliases": [], "era": "元末", "birth_year": null, "death_year": null, "description": "赵忠养子，袭其职，后复姓王，守太平死。", "biography": null, "status": "draft", "id": "8a393446-6519-5c46-aed6-db52a5c4b74c"}, {"status": "draft", "name": "徐寿辉", "aliases": [], "era": "元", "birth_year": null, "death_year": null, "description": "罗田人，原贩布，1351年在蕲黄以红巾起兵，被推为主，后建天完称帝。", "biography": null, "id": "168b2da9-205f-5285-b0b0-4618e5ef57a4"}, {"name": "张士诚", "aliases": [], "era": "元", "birth_year": null, "death_year": null, "description": "白驹场盐民，率众起兵，陷高邮称诚王建周。", "biography": null, "status": "draft", "id": "7fbe0af4-cc39-5fb7-9fa8-c94e110ad986"}, {"name": "耿再成", "aliases": [], "era": "元", "birth_year": null, "death_year": null, "description": "1354—55年从朱元璋守战六合和阳。", "biography": null, "status": "draft", "id": "e2654eb1-d625-5630-ab59-98ae745307ea"}, {"status": "draft", "name": "欧普祥", "aliases": [], "era": "元", "birth_year": null, "death_year": null, "description": "黄冈人，号欧道人，聚众从徐寿辉为元帅，1352年攻陷袁州。", "biography": null, "id": "cb7da9d8-1bfc-57c4-82ef-48edacbf3c57"}, {"name": "薛显", "aliases": [], "era": "元末", "birth_year": null, "death_year": null, "description": "泗州守将，献城降吴。", "biography": null, "status": "draft", "id": "890acdc0-4ba1-5b99-8fcf-b667c224015f"}, {"name": "张定边", "aliases": [], "era": "元末", "birth_year": null, "death_year": null, "description": "陈友谅将，称帝时授太尉。", "biography": null, "status": "draft", "id": "f47481fa-0db7-5731-aa40-81d432adfef8"}, {"status": "draft", "name": "丁普郎", "aliases": [], "era": "元", "birth_year": null, "death_year": null, "description": "徐寿辉部将，1352年攻陷汉阳兴国。", "biography": null, "id": "b010dc16-ab73-5a28-b9e4-1d7ef88ceb03"}, {"name": "傅友德", "aliases": [], "era": "元末", "birth_year": null, "death_year": null, "description": "原陈友谅小孤山守将，1361年降吴。", "biography": null, "status": "draft", "id": "052c6ab9-234a-5d89-9bad-ec31f6774b50"}, {"name": "标（朱元璋长子）", "aliases": [], "era": "元末", "birth_year": null, "death_year": null, "description": "朱元璋长子，从宋濂受经；本段未补姓。", "biography": null, "status": "draft", "id": "53419f1e-1783-5056-b47a-6af23b967a6f"}]'::jsonb)
ON CONFLICT (id) DO NOTHING;

INSERT INTO public.event (id, title, start_year, end_year, time_original, dynasty, description, phases, location_name, location_modern_name, location_lat, location_lng, location_precision, location_note, status)
SELECT id, title, start_year, end_year, time_original, dynasty, description, phases, location_name, location_modern_name, location_lat, location_lng, location_precision, location_note, status FROM jsonb_populate_recordset(NULL::public.event, '[{"title": "朱元璋命康茂才主管营田和水利", "description": "朱元璋任命康茂才为营田使，负责修筑堤防、整治水利，妥善蓄水排水，防备旱涝。他告诫康茂才，设官本为百姓谋利，不可只让地方官修饰馆舍、奔走迎送，反而扰害百姓。", "start_year": 1358, "end_year": 1358, "time_original": "《续资治通鉴》卷214；本事原载纪年折合公元1358年，具体月日依引文。", "dynasty": "元及同时诸政权", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "fb05fa54-e18e-55c4-b9a1-6ebf2819f34c"}, {"title": "朱元璋一方审查在押囚犯的案件", "description": "三月己酉，朱元璋一方审查在押囚犯的案件。", "start_year": 1358, "end_year": 1358, "time_original": "至正十八年三月", "dynasty": "元及同时诸政权", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "625ab9e4-40ad-52ce-a201-b0cbb473c582"}, {"title": "邓愈等攻下建德，改置严州府", "description": "邓愈、朱文忠、胡大海进攻建德，先在遂安击败余子贞，追至淳安，招降三千余人；又击败洪姓守将的援军，俘获四百余人。大军抵达建德时，布哈、庆寿等逃走，何良辅等父老献城。建德路随后改为严州府。", "start_year": 1358, "end_year": 1358, "time_original": "《续资治通鉴》卷214；本事原载纪年折合公元1358年，具体月日依引文。", "dynasty": "元及同时诸政权", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "54ab25c0-3552-5f21-9efd-51b291e236ba"}, {"title": "赵普胜攻下池州，俘获赵忠", "description": "赵普胜从枞阳进攻池州，攻下城池，俘获朱元璋守将赵忠。", "start_year": 1358, "end_year": 1358, "time_original": "《续资治通鉴》卷214；本事原载纪年折合公元1358年，具体月日依引文。", "dynasty": "元及同时诸政权", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "f69be9f1-818c-577b-9016-b01203e1327b"}, {"title": "陈友谅攻陷龙兴，道通、和尼齐弃城", "description": "陈友谅攻陷龙兴，道通、和尼齐弃城逃走。", "start_year": 1358, "end_year": 1358, "time_original": "《续资治通鉴》卷214；本事原载纪年折合公元1358年，具体月日依引文。", "dynasty": "元及同时诸政权", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "bfbbdbfe-a93a-5d88-9e6d-29c154ce938e"}, {"title": "刘福通攻占汴梁，迎韩林儿迁都", "description": "刘福通进攻汴梁，守将珠展弃城逃走。刘福通进入城中，修建宫殿，从安丰迎来韩林儿，以汴梁为都城。", "start_year": 1358, "end_year": 1358, "time_original": "《续资治通鉴》卷214；本事原载纪年折合公元1358年，具体月日依引文。", "dynasty": "元及同时诸政权", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "b3db5604-9380-5ef8-839f-56c1f68bbb12"}, {"title": "朱元璋亲率十万军进攻婺州", "description": "胡大海进攻婺州未能攻克，朱元璋于是亲率杨璟等及十万军前往进攻。", "start_year": 1358, "end_year": 1358, "time_original": "《续资治通鉴》卷214；本事原载纪年折合公元1358年，具体月日依引文。", "dynasty": "元及同时诸政权", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "2f4760fc-19fb-5195-b622-13df66e4af65"}, {"title": "舒穆嚕宜逊派兵援婺州，胡深等战败", "description": "舒穆嚕厚逊守卫婺州，舒穆嚕宜逊的母亲也在城中。舒穆嚕宜逊以君亲大义为由，派胡深等率数万民兵先行援救，自己率精锐殿后。朱元璋判断战车不利于山间险道。次日，胡大海养子德济在梅花门外诱出援军，将其击败。胡深等退去，城中处境更加孤立。", "start_year": 1358, "end_year": 1358, "time_original": "《续资治通鉴》卷214；本事原载纪年折合公元1358年，具体月日依引文。", "dynasty": "元及同时诸政权", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "6963956a-fd22-5af7-a3ef-1dbff85aff88"}, {"title": "朱元璋军攻下婺州，杨惠、僧珠战死", "description": "朱元璋的军队攻取婺州。宁安庆、李相从城内开门，杨惠、僧珠战死，特穆尔赉斯、舒穆嚕厚逊等被俘。朱元璋入城后禁止军士掳掠，将婺州改为宁越府，设中书分省，又召许元、叶瓒、胡翰、汪仲山等儒士轮流讲说治道。", "start_year": 1358, "end_year": 1358, "time_original": "《续资治通鉴》卷214；本事原载纪年折合公元1358年，具体月日依引文。", "dynasty": "元及同时诸政权", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "ff544190-621f-52f1-918e-1eacd1051fe2"}, {"title": "朱元璋告诫攻取浙东的将领不可滥杀", "description": "至正十九年正月，朱元璋筹划攻取浙东尚未攻下的州郡。他告诫将领，军队攻城后不得滥杀，并以自己进入集庆时不侵扰百姓为例。", "start_year": 1359, "end_year": 1359, "time_original": "至正十九年正月", "dynasty": "元及同时诸政权", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "1c7c5268-fec2-5a08-98d5-83a1368c658e"}, {"title": "朱元璋军攻临安未成，攻取诸暨并接受嵊县投降", "description": "王遇成、孙茂先进攻临安，击败李伯升的援军，但未能攻破城池，随后撤回。胡大海进攻诸暨，守将连夜逃走，沈胜率众投降。朱元璋一方将诸暨改为诸全，嵊县万户郝原也请求投降。", "start_year": 1359, "end_year": 1359, "time_original": "《续资治通鉴》卷215；本事原载纪年折合公元1359年，具体月日依引文。", "dynasty": "元及同时诸政权", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "7666ce6b-b4a1-56e5-8c1d-8cef8fd71b3f"}, {"title": "王宗显任宁越知府，奉命创办郡学", "description": "王宗显被任命为宁越知府，奉命开办郡学，延请叶仪、宋濂讲授五经，以戴良为学正，吴沈、徐厚为训导。战乱中停废的讲诵由此恢复。", "start_year": 1358, "end_year": 1358, "time_original": "《续资治通鉴》卷214；本事原载纪年折合公元1358年，具体月日依引文。", "dynasty": "元及同时诸政权", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "33d491d5-853f-58a3-9acf-d1e0c039ee89"}, {"title": "朱元璋一方下令赦免罪囚", "description": "三月甲午，朱元璋一方下令大赦，赦免范围依本纪所载为大逆以下。", "start_year": 1359, "end_year": 1359, "time_original": "至正十九年三月", "dynasty": "元及同时诸政权", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "c3bf4614-f7ab-5288-a737-a9353055ed1d"}, {"title": "方国珍献三路并送质子，朱元璋将关遣回", "description": "方国珍派张本仁献上温州、台州、庆元三路，又送次子关来作人质。朱元璋认为，互送人质源于彼此不信任，既然已经来归，就应诚心相待。他厚赏关，将他送回。关后来改名明完。", "start_year": 1359, "end_year": 1359, "time_original": "《续资治通鉴》卷215；本事原载纪年折合公元1359年，具体月日依引文。", "dynasty": "元及同时诸政权", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "0d3b52b4-0f66-5f20-b53a-0ab75647c55c"}, {"title": "徐达派俞通海击败赵普胜部，收复池州", "description": "赵普胜占据枞阳水寨，多次侵扰劫掠。徐达派俞通海等进攻，俘获赵牛儿、洪钧等人，缴获数百艘战船。赵普胜弃船从陆路逃走，朱元璋军收复池州。", "start_year": 1359, "end_year": 1359, "time_original": "《续资治通鉴》卷215；本事原载纪年折合公元1359年，具体月日依引文。", "dynasty": "元及同时诸政权", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "9cf37e8f-c8b6-5b5d-823b-263e8fee00bb"}, {"title": "朱元璋从浙东返回应天", "description": "六月壬戌，朱元璋从浙东返回应天。", "start_year": 1359, "end_year": 1359, "time_original": "至正十九年六月", "dynasty": "元及同时诸政权", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "44cea816-10c4-5f74-a5f0-074867560e3a"}, {"title": "察罕特穆尔攻破汴梁，刘福通护送韩林儿逃往安丰", "description": "察罕特穆尔得知汴梁城中粮食耗尽，与阎思孝、李克彝、虎林赤等分头攻打城门，在戊寅夜间破城而入。刘福通护送小明王韩林儿从东门逃出，继续占据安丰。元军俘获其后妃家属和官员，保全居民二十万，军纪严明，不久河南平定。元廷任命察罕特穆尔为河南平章，兼知行枢密院事、陕西行台中丞等，仍准许他根据当地情况自行处置事务。", "start_year": 1359, "end_year": 1359, "time_original": "《续资治通鉴》卷215；本事原载纪年折合公元1359年，具体月日依引文。", "dynasty": "元及同时诸政权", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "5dffc37b-ba79-5d91-a3f4-7570c7cbac39"}, {"title": "张斌开门内应，常遇春攻取衢州", "description": "常遇春围攻衢州两个多月，张斌判断难以守住，秘密约定投降，夜间从小西门迎入朱元璋军。宋巴延布哈并不知情，仍在督促防守；起火、敌军入城后，守军溃散。冯浩投水而死，宋巴延布哈、都尼等被俘。朱元璋一方将衢州改为龙游府，升常遇春为佥枢密院。", "start_year": 1359, "end_year": 1359, "time_original": "《续资治通鉴》卷215；本事原载纪年折合公元1359年，具体月日依引文。", "dynasty": "元及同时诸政权", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "3ba93679-6c94-5ba4-b547-aecc3f10b713"}, {"title": "方国珍接受朱元璋所授平章印信，却称病不任职", "description": "朱元璋派夏煜授方国珍福建平章，授其弟国瑛参政、国珉佥枢密分院事，并给他们符印，让他们仍守原部，等待调遣。方国珍想拒绝，又顾虑已经归降；想接受，又担心受制。他于是称病，只接受印信，告老而不任职，对使者态度傲慢。只有国珉设院办事。", "start_year": 1359, "end_year": 1359, "time_original": "《续资治通鉴》卷215；本事原载纪年折合公元1359年，具体月日依引文。", "dynasty": "元及同时诸政权", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "481ebd22-6fc8-5952-adb3-7bc6d0b10dfb"}, {"title": "胡大海、耿再成攻取处州", "description": "李国凤此前任命舒穆嚕伊逊为江浙参政，守卫处州。朱元璋派耿再成驻扎黄龙山，准备进攻，胡大海后来与他会合，攻打桃花岭、葛渡等寨。刘基先前已经弃官归去，守军失去谋划者，军心涣散。舒穆嚕伊逊战败逃走，朱元璋军攻取处州。", "start_year": 1359, "end_year": 1359, "time_original": "《续资治通鉴》卷215；本事原载纪年折合公元1359年，具体月日依引文。", "dynasty": "元及同时诸政权", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "22c1aa0a-0fbd-5314-a218-b67106e5237e"}, {"title": "袁天禄、张希伯向朱元璋请降", "description": "赛甫鼎、阿里密鼎占据泉州，陈友谅军又从杉关进攻福建，地方动荡。福建行省参政袁天禄认为元朝国势难以振作，派古田县尹林文广从海路送信给朱元璋，表示归顺；福清州同知张希伯也派人请降。朱元璋厚赏来使，让他们返回劝当地人归顺。", "start_year": 1360, "end_year": 1360, "time_original": "《续资治通鉴》卷215；本事原载纪年折合公元1360年，具体月日依引文。", "dynasty": "元及同时诸政权", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "f9e29f61-8968-59db-91fe-4921d7e72cf7"}, {"title": "朱元璋延聘刘基、章溢、叶琛、宋濂", "description": "胡大海推荐刘基等四人，朱元璋派使者携书信和礼物延聘。孙炎反复写信劝说刘基，四人终于一同来到建康。朱元璋以礼相待，向他们询问平定天下的办法。章溢说，不嗜杀的人能够统一天下；刘基陈述十八项时务建议，主张先攻陈友谅，再对付张士诚。朱元璋听后非常高兴，设礼贤馆安置四人。", "start_year": 1360, "end_year": 1360, "time_original": "《续资治通鉴》卷215；本事原载纪年折合公元1360年，具体月日依引文。", "dynasty": "元及同时诸政权", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "cbd9e755-8591-5169-8b02-dc487ee7f013"}, {"title": "徐达等击败进攻池州的军队，常遇春先行坑杀俘虏", "description": "朱元璋先命徐达、常遇春带五千人守池州，另派一万人埋伏九华山。陈友谅军到达后，守军击鼓举旗，伏兵切断其后路，城内外军队夹击，斩杀万余人，俘获三千余人。常遇春认为敌兵强悍，应该杀掉，徐达反对，并向朱元璋报告。朱元璋派使者命令释放俘虏，但常遇春此前已经趁夜将他们坑杀，只剩三百人。朱元璋得知后不悦，命令将剩余俘虏全部放回。", "start_year": 1360, "end_year": 1360, "time_original": "《续资治通鉴》卷215；本事原载纪年折合公元1360年，具体月日依引文。", "dynasty": "元及同时诸政权", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "bb5928c0-88a0-5645-bccb-cff60600a3df"}, {"title": "陈友谅攻陷太平，花云等人死难", "description": "陈友谅率水军攻打太平，花云与朱文逊等带三千人抵御，朱文逊战死。陈友谅攻了三天未能入城，便用巨舰靠近城墙，让士卒沿船尾攀上城墙，城池随即失守。花云被绑后挣断绳索，夺刀砍杀五六人，又被绑在船桅上，遭乱箭射死。王鼎、许瑗也因被俘后抗骂不屈而遇害。", "start_year": 1360, "end_year": 1360, "time_original": "《续资治通鉴》卷215；本事原载纪年折合公元1360年，具体月日依引文。", "dynasty": "元及同时诸政权", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "027972d6-9f3a-5b1b-b346-de2cf33a03ad"}, {"title": "陈友谅杀死徐寿辉，自立为汉帝", "description": "陈友谅带着徐寿辉攻打太平。城池失守后，他在采石的船中派人假装到徐寿辉面前禀事，让壮士从背后用铁锤击碎徐寿辉的头。随后，陈友谅以五通庙作行殿，称帝，国号汉，改元大义，任邹普胜为太师、张必先为丞相、张定边为太尉。群臣在江岸草草行礼，恰遇大雨，衣冠都被淋湿。", "start_year": 1360, "end_year": 1360, "time_original": "《续资治通鉴》卷215；本事原载纪年折合公元1360年，具体月日依引文。", "dynasty": "元及同时诸政权", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "2f380f5a-986e-58c0-8337-c59045589033"}, {"title": "陈友谅邀张士诚合攻建康，未等答复便出兵", "description": "陈友谅遣使约张士诚同攻建康，未等对方答复，便从采石率舟师东下，建康震动。", "start_year": 1360, "end_year": 1360, "time_original": "《续资治通鉴》卷215；本事原载纪年折合公元1360年，具体月日依引文。", "dynasty": "元及同时诸政权", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "de68ffa5-a1c4-5181-a2f7-16a49f5e22a2"}, {"title": "朱元璋令康茂才假意投降，诱陈友谅分兵", "description": "朱元璋否决亲自出兵迎击的建议，认为敌军可能趁机直趋建康。他命胡大海进攻信州，牵制陈友谅的后方，又令康茂才利用旧交关系，写信假意投降，约作内应，催陈友谅尽快来攻并分兵。康茂才提出，让曾侍奉陈友谅的年老守门仆人送信。李善长问为何反而催促敌军，朱元璋说，必须在陈友谅、张士诚联手前先击败陈友谅，才能震慑张士诚。", "start_year": 1360, "end_year": 1360, "time_original": "《续资治通鉴》卷215；本事原载纪年折合公元1360年，具体月日依引文。", "dynasty": "元及同时诸政权", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "d5865709-b901-5886-ada5-82ee49ce845e"}, {"title": "朱元璋军在龙湾大败陈友谅", "description": "陈友谅的水军到大胜港，因港口狭窄，只能容两船进入，又受杨璟抵御，便退回大江，转攻江东桥。他见桥已换成铁石，呼喊“老康”无人回应，知道受骗，便与弟弟友仁率千余艘船前往龙湾，先派一万人登岸筑栅。朱元璋趁骤雨举红旗进攻，雨停后击鼓，再举黄旗，伏兵和水陆各军共同夹击。陈友谅军溃败，登船逃走时又遇退潮，船只搁浅，被杀、溺死者无数。朱元璋军俘获二万余人、百余艘巨舰，张志雄、梁铉、喻兴、刘世衍等投降。陈友谅乘小船逃走。", "start_year": 1360, "end_year": 1360, "time_original": "《续资治通鉴》卷215；本事原载纪年折合公元1360年，具体月日依引文。", "dynasty": "元及同时诸政权", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "7d4c1db4-bea7-569b-977b-42944472cc6a"}, {"title": "胡大海采纳王恺建议攻取信州，朱元璋禁止征收寨粮", "description": "朱元璋命胡大海攻信州，牵制陈友谅的后方。胡大海先派葛俊领兵，王恺担心这支部队不足以攻下信州，劝胡大海亲率全军。胡大海采纳，在灵溪击败出城迎战的守军，随后攻下信州。胡大海又报告，将士向新归附郡县的百姓征收所谓寨粮，百姓深受其害。朱元璋立即下令停止。", "start_year": 1360, "end_year": 1360, "time_original": "《续资治通鉴》卷215；本事原载纪年折合公元1360年，具体月日依引文。", "dynasty": "元及同时诸政权", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "f066eeda-7a78-5c33-b8d8-caa5137cbf2c"}, {"title": "舒穆嚕伊逊谋求收复处州，战死后获朱元璋祭奠", "description": "舒穆嚕伊逊的母亲被朱元璋军俘获后，其弟送信来招降，他没有接受。处州失守后，他逃到建宁聚兵，想重新收复失地。局势困窘，他仍进攻庆元，被耿再成击败。舒穆嚕伊逊逃往竹口，准备返回福建，经过桃花坑时遭乡兵截击，力战而死，部将李文彦将他收葬。孙炎报告后，朱元璋赞赏他的忠义，派人祭奠，并恢复处州百姓为他所立的生祠。", "start_year": 1360, "end_year": 1360, "time_original": "《续资治通鉴》卷215；本事原载纪年折合公元1360年，具体月日依引文。", "dynasty": "元及同时诸政权", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "b72a716f-f251-571f-a713-6a0e396cf075"}, {"title": "欧普祥归降朱元璋，擒获友仁后放归", "description": "徐寿辉旧将欧普祥驻守袁州，此前行军残暴，沿途焚掠。陈友谅杀死徐寿辉后向他征兵，欧普祥拒不听命，献袁州归降朱元璋。陈友谅派弟弟友仁进攻，欧普祥与刘仁、黄彬击败来军，俘获友仁，鞭打后囚禁。陈友谅派邹普胜议和，约定各守边界，欧普祥于是放友仁回去。", "start_year": 1360, "end_year": 1360, "time_original": "《续资治通鉴》卷216；本事原载纪年折合公元1360年，具体月日依引文。", "dynasty": "元及同时诸政权", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "864c435a-864a-527c-9846-0f6fb20c3a9f"}, {"title": "夏煜再奉书谕方国珍", "description": "朱元璋再次遣夏煜持书招谕方国珍。", "start_year": 1360, "end_year": 1360, "time_original": "《续资治通鉴》卷216；本事原载纪年折合公元1360年，具体月日依引文。", "dynasty": "元及同时诸政权", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "0e41afbc-b435-53f4-b4a2-cdc59748344a"}, {"title": "应天设宝源局，铸行大中通宝", "description": "朱元璋一方在应天设置宝源局，铸造大中通宝，与历代旧钱一同使用。原定四百文为一贯、四贯为一两、四文为一钱，货物价格由民间交易决定。", "start_year": 1361, "end_year": 1361, "time_original": "《续资治通鉴》卷216；本事原载纪年折合公元1361年，具体月日依引文。", "dynasty": "元及同时诸政权", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "2251d541-45a2-516a-be50-74f55d16102c"}, {"title": "薛显献泗州归降朱元璋", "description": "泗州守将薛显献城归降朱元璋。", "start_year": 1361, "end_year": 1361, "time_original": "《续资治通鉴》卷216；本事原载纪年折合公元1361年，具体月日依引文。", "dynasty": "元及同时诸政权", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "ec8d917c-9f3b-561c-8e4b-ca01f43832b2"}, {"title": "朱元璋拒方国珍金玉鞍舆", "description": "方国珍使者来谢招谕，献金玉装饰的马鞍车舆，朱元璋称四方用兵只需人才与粮帛，不爱珍玩，拒收。", "start_year": 1361, "end_year": 1361, "time_original": "《续资治通鉴》卷216；本事原载纪年折合公元1361年，具体月日依引文。", "dynasty": "元及同时诸政权", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "35c11eb3-0493-5fa0-8459-e9fae2014458"}, {"title": "张定边攻陷安庆，败将余某返还后被杀", "description": "陈友谅将张定边攻陷安庆，吴守将余某战败逃回建康，朱元璋怒而斩之。", "start_year": 1361, "end_year": 1361, "time_original": "《续资治通鉴》卷216；本事原载纪年折合公元1361年，具体月日依引文。", "dynasty": "元及同时诸政权", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "1c107bb4-21f4-5a6b-9ad8-0b4d9743b7a4"}, {"title": "朱元璋派使通好察罕特穆尔，以观察其回应", "description": "朱元璋听说察罕特穆尔获胜，派使者与他通好。朱元璋向左右批评说，察罕特穆尔屡违诏命、与博囉特穆尔争地，又把反复无常的田丰当作心腹，不像能洞察形势的名将。他说明，遣使是想观察察罕特穆尔如何回应，再作打算。", "start_year": 1361, "end_year": 1361, "time_original": "《续资治通鉴》卷216；本事原载纪年折合公元1361年，具体月日依引文。", "dynasty": "元及同时诸政权", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "ac6551e8-7172-5c7b-a0dd-afa49d7fb47c"}, {"title": "朱元璋水军收复安庆并攻下江州", "description": "朱元璋命徐达、常遇春先行，自己乘龙骧巨舰率舟师溯江而上。安庆守军坚守不出，他用陆军牵制，又命廖永忠、张志雄攻破敌军水寨，缴获八十余艘战船，收复安庆。小孤山守将傅友德、丁普郎归降后，常遇春追击巡江敌船至江州，朱元璋分水军两翼夹攻，缴获百余艘战船。陈友谅夜间带家人逃往武昌，朱元璋进入江州，派徐达追击。徐达得知陈友谅准备从沔阳出动战舰迎战，便驻军沌口阻遏。", "start_year": 1361, "end_year": 1361, "time_original": "《续资治通鉴》卷216；本事原载纪年折合公元1361年，具体月日依引文。", "dynasty": "元及同时诸政权", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "6ced9321-ac4d-5753-937e-a150a4c8b0ae"}, {"title": "邓愈袭取抚州，邓克明降后逃归", "description": "朱元璋一方派吴弘等进攻抚州，邓克明据城抵抗。邓愈从小路夜袭，迫使邓克明出降，命其弟志明收集旧部。邓克明请求去江州见朱元璋，却在赴江州途中逃回新淦。", "start_year": 1361, "end_year": 1361, "time_original": "《续资治通鉴》卷216；本事原载纪年折合公元1361年，具体月日依引文。", "dynasty": "元及同时诸政权", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "340ddcb6-c023-56f1-9526-27e6d703cb46"}, {"title": "宋濂主管儒学提举司，教授朱元璋长子标", "description": "朱元璋设儒学提举司，以宋濂为提举，命长子标跟从宋濂学习经书。宋濂常在朱元璋身边，受命讲解《春秋左氏传》时，劝他遵行褒扬善行、贬斥恶行的原则，使赏罚得当，安定天下。", "start_year": 1360, "end_year": 1360, "time_original": "《续资治通鉴》卷215；本事原载纪年折合公元1360年，具体月日依引文。", "dynasty": "元及同时诸政权", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "6d0d706c-5620-581c-998f-c994f59aed81"}]'::jsonb)
ON CONFLICT (id) DO NOTHING;

